size_t pw_menu_slot_size(const pw_menu_slot_t *s)
{
    return (size_t)s->w * (size_t)(s->h / 8) * 2u;
}

void pw_menu_art_fill(uint8_t *eeprom64k)
{
    // white everywhere in the art range first (unused/unknown gaps)
    memset(eeprom64k + PW_MENU_ART_START, 0, PW_MENU_ART_END - PW_MENU_ART_START);
    for (int i = 0; i < PW_MENU_SLOT_COUNT; i++) {
        const pw_menu_slot_t *s = &pw_menu_slots[i];
        size_t n = pw_menu_slot_size(s);
        if (s->addr < PW_MENU_ART_START || s->addr + n > PW_MENU_ART_END)
            continue; // never write outside 0x0280-0x8C6F
        if (s->data)
            memcpy(eeprom64k + s->addr, s->data, n);
    }
}
